  <script>
    const arabicMonths = [
      "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
      "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
    ];
    const arabicDays = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];
    const today = new Date();
    let viewMonth = new Date(today.getFullYear(), today.getMonth(), 1);
    let selectedDate = null;
    let selectedTime = null;

    const daysElement = document.getElementById("days");
    const monthName = document.getElementById("month-name");
    const selectedDateText = document.getElementById("selected-date");
    const summary = document.getElementById("booking-summary");
    const confirmButton = document.getElementById("confirm");
    const toast = document.getElementById("toast");

    function sameDay(a, b) {
      return a && b &&
        a.getFullYear() === b.getFullYear() &&
        a.getMonth() === b.getMonth() &&
        a.getDate() === b.getDate();
    }

    function formatSelectedDate(date) {
      return `${arabicDays[date.getDay()]} ${date.getDate()} ${arabicMonths[date.getMonth()]}`;
    }

    function renderCalendar() {
      monthName.textContent = `${arabicMonths[viewMonth.getMonth()]} ${viewMonth.getFullYear()}`;
      daysElement.innerHTML = "";

      const year = viewMonth.getFullYear();
      const month = viewMonth.getMonth();
      const firstDay = new Date(year, month, 1);
      const offset = (firstDay.getDay() + 1) % 7;
      const start = new Date(year, month, 1 - offset);
      const todayDate = new Date(today.getFullYear(), today.getMonth(), today.getDate());

      for (let i = 0; i < 42; i++) {
        const date = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
        const button = document.createElement("button");
        button.type = "button";
        button.className = "day";
        button.textContent = date.getDate();
        button.setAttribute("role", "gridcell");
        button.setAttribute("aria-label", formatSelectedDate(date));

        if (date.getMonth() !== month) button.classList.add("other");
        if (sameDay(date, todayDate)) {
          button.classList.add("today");
          button.setAttribute("aria-current", "date");
        }
        if (sameDay(date, selectedDate)) {
          button.classList.add("selected");
          button.setAttribute("aria-selected", "true");
        }

        button.addEventListener("click", () => {
          selectedDate = new Date(date);
          renderCalendar();
          updateSelection();
        });

        daysElement.appendChild(button);
      }
    }

    function updateSelection() {
      const hasDate = !!selectedDate;
      const hasTime = !!selectedTime;

      selectedDateText.textContent = hasDate
        ? formatSelectedDate(selectedDate)
        : "حدد يومًا من التقويم";

      summary.textContent = hasDate
        ? (hasTime
          ? `الموعد المختار: ${formatSelectedDate(selectedDate)}، الساعة ${selectedTime}`
          : `التاريخ المختار: ${formatSelectedDate(selectedDate)} — اختر الوقت`)
        : "سيظهر ملخص الموعد هنا بعد اختيار التاريخ والوقت.";

      confirmButton.disabled = !(hasDate && hasTime);
    }

    document.getElementById("prev-month").addEventListener("click", () => {
      viewMonth = new Date(viewMonth.getFullYear(), viewMonth.getMonth() - 1, 1);
      renderCalendar();
    });

    document.getElementById("next-month").addEventListener("click", () => {
      viewMonth = new Date(viewMonth.getFullYear(), viewMonth.getMonth() + 1, 1);
      renderCalendar();
    });

    document.querySelectorAll(".time").forEach(button => {
      button.addEventListener("click", () => {
        document.querySelectorAll(".time").forEach(item => item.classList.remove("selected"));
        button.classList.add("selected");
        selectedTime = button.dataset.time;
        updateSelection();
      });
    });

    confirmButton.addEventListener("click", () => {
      if (!selectedDate || !selectedTime) return;
      toast.classList.add("show");
      setTimeout(() => toast.classList.remove("show"), 2600);
    });

    document.querySelector(".back-button").addEventListener("click", () => {
      window.history.length > 1 ? window.history.back() : toast.textContent = "أنت في شاشة حجز الموعد";
    });

    renderCalendar();
    updateSelection();
  </script>
</body>
